-- 27 September 2026 daily current-affairs desk.
-- Every brief was checked against the linked primary official source.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-27-cgtmse-guarantee-cover-treds$$, $$2026-09-27$$,
  $$CGTMSE guarantee cover goes live on three TReDS platforms$$,
  $$The MSME Ministry has made CGTMSE credit-guarantee cover available for eligible invoice discounting on M1xchange, RXIL and DTX (KredX). The change is intended to improve working-capital access when micro and small enterprises sell unpaid invoices through TReDS.$$,
  $$This connects MSME policy with formal credit and delayed-payment reform. It is a useful distinction: TReDS discounts receivables; CGTMSE absorbs part of the default risk rather than making an ordinary grant.$$,
  $$TReDS is an RBI-regulated electronic system where financiers competitively finance MSME receivables owed by corporates, government departments or PSUs. Under the new special provision, the official release states that both buyer and seller must be micro or small enterprises; guarantee cover is 75% of the default amount, subject to stated revolving exposure limits.$$,
  $$CGTMSE Guarantee Cover Goes Live on TReDS to Strengthen MSME Working Capital Access$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314945&lang=1&reg=3$$,
  $$Ministry of Micro, Small and Medium Enterprises / Press Information Bureau$$, $$2026-09-25$$,
  $$["TReDS is an RBI-regulated electronic receivables-financing platform.","CGTMSE cover is live on M1xchange, RXIL and DTX (KredX).","The stated guarantee cover is 75% of the amount in default.","For this special provision, both buyer and seller must be micro or small enterprises."]$$::jsonb,
  $$[{"question":"What cash-flow problem does invoice discounting address?","answer":"It lets an enterprise receive money against an unpaid invoice before the buyer pays it."},{"question":"Which regulator oversees TReDS?","answer":"The Reserve Bank of India."}]$$::jsonb,
  $${"title":"From invoice to working capital","steps":["An MSE supplies goods or services and raises an invoice.","The unpaid invoice is listed on TReDS for financier bidding.","A financier discounts the receivable; CGTMSE cover reduces eligible default risk.","The MSE receives working capital sooner."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-quad-at-sea-ship-observer-mission$$, $$2026-09-27$$,
  $$ICG Ship Shaunak sails for the QUAD-at-Sea observer mission$$,
  $$Indian Coast Guard Ship Shaunak sailed from Chennai to Perth for the QUAD-at-Sea Ship Observer Mission. Six Sea Riders from India, Japan, Australia and the United States will take part in shipboard activities and professional exchanges.$$,
  $$This is an Indo-Pacific maritime-cooperation update. It tests the QUAD’s membership and the difference between interoperability exercises and a treaty-based military alliance.$$,
  $$The QUAD groups India, Australia, Japan and the United States. The release links the mission to the Quad Foreign Ministers’ Joint Statement of 26 May 2026 and to India’s MAHASAGAR vision—Mutual and Holistic Advancement for Security and Growth Across Regions.$$,
  $$ICG to strengthen maritime cooperation through QUAD-at-Sea Ship Observer Mission$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2315065&lang=2&reg=48$$,
  $$Indian Coast Guard, Ministry of Defence / Press Information Bureau$$, $$2026-09-25$$,
  $$["QUAD members are India, Australia, Japan and the United States.","ICG Ship Shaunak sailed from Chennai for Perth, Australia.","The mission includes six Sea Riders from the four QUAD countries.","MAHASAGAR expands to Mutual and Holistic Advancement for Security and Growth Across Regions."]$$::jsonb,
  $$[{"question":"Which country is not a QUAD member: Japan, Australia, France or the United States?","answer":"France is not a QUAD member."},{"question":"What is the purpose of the observer mission?","answer":"To improve maritime interoperability, coordination and professional links among QUAD partners."}]$$::jsonb,
  $${"title":"How observer missions build maritime cooperation","steps":["Partner countries place officers aboard a participating ship.","They observe procedures and work together at sea.","Common operating understanding and trust improve.","Future coordination in the Indo-Pacific becomes easier."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-trai-digital-connectivity-rating-platform$$, $$2026-09-27$$,
  $$TRAI launches a public digital-connectivity rating platform for properties$$,
  $$TRAI launched the Digital Connectivity Rating platform to manage and display ratings of properties’ digital-connectivity readiness. It links property managers, registered rating agencies and consumers, and supports applications, testing, certification and public verification.$$,
  $$This is a telecom-regulation and digital-infrastructure update. It asks students to separate a property-connectivity rating from a mobile-service quality survey or a telecom operator’s consumer tariff.$$,
  $$The platform implements TRAI’s Rating of Properties for Digital Connectivity Regulations, 2024, as amended in 2026, and the 2026 Rating Manual. Assessments consider factors such as fibre readiness, mobile-network availability, in-building solutions and Wi-Fi infrastructure.$$,
  $$TRAI Launches Digital Connectivity Rating Platform$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314867&lang=1&reg=3$$,
  $$Telecom Regulatory Authority of India / Press Information Bureau$$, $$2026-09-25$$,
  $$["TRAI launched the Digital Connectivity Rating platform.","The framework covers fibre readiness, mobile availability, in-building solutions and Wi-Fi infrastructure.","Registered Digital Connectivity Rating Agencies conduct assessments.","Consumers can search ratings and verify certificates using a QR code."]$$::jsonb,
  $$[{"question":"Which body launched the Digital Connectivity Rating platform?","answer":"The Telecom Regulatory Authority of India (TRAI)."},{"question":"Name one assessment area under the framework.","answer":"For example, fibre readiness, mobile-network availability, in-building solutions or Wi-Fi infrastructure."}]$$::jsonb,
  $${"title":"Property connectivity rating workflow","steps":["A property manager applies through the platform.","A registered rating agency conducts the prescribed assessment.","Results are recorded and a certificate is issued digitally.","Consumers can search and verify the published rating."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-fcv-tobacco-growers-interest-free-loan$$, $$2026-09-27$$,
  $$Centre approves one-time interest-free working-capital support for FCV tobacco growers$$,
  $$The Union government approved a one-time interest-free loan of ₹50,000 per barn for Flue-Cured Virginia tobacco growers in Andhra Pradesh. The release estimates coverage of about 44,000 growers and a financial intervention of around ₹220 crore through direct benefit transfer.$$,
  $$This is an agriculture-market intervention. Remember the crop form and the targeted State; do not generalise it into a nationwide farm-income scheme.$$,
  $$Flue-Cured Virginia tobacco is mainly cultivated in Andhra Pradesh and Karnataka. The support is framed as working capital: liquidity that can help growers meet household needs, repay institutional loans and buy inputs, rather than a price-support mechanism.$$,
  $$Government Approves One-Time Interest-Free Loan of ₹50,000 per Barn for FCV Tobacco Growers in Andhra Pradesh$$,
  $$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2315004&lang=2&reg=48$$,
  $$Ministry of Commerce and Industry / Press Information Bureau$$, $$2026-09-25$$,
  $$["FCV means Flue-Cured Virginia tobacco.","The one-time support is ₹50,000 per barn for eligible growers in Andhra Pradesh.","The release estimates about 44,000 growers and around ₹220 crore in intervention.","FCV tobacco is predominantly grown in Andhra Pradesh and Karnataka."]$$::jsonb,
  $$[{"question":"What does FCV stand for in this support measure?","answer":"Flue-Cured Virginia."},{"question":"Is this a nationwide scheme for every tobacco grower?","answer":"No. The cited approval is a one-time intervention for FCV growers in Andhra Pradesh."}]$$::jsonb,
  $${"title":"Targeted working-capital support","steps":["A sector faces difficult marketing and liquidity conditions.","Government defines an eligible producer group and assistance amount.","Support is transferred directly to eligible growers.","Growers can use it for short-term household, debt or input needs."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-india-h2-market-borrowing-plan$$, $$2026-09-27$$,
  $$Government sets its H2 FY 2026-27 market-borrowing plan at ₹7.86 lakh crore$$,
  $$In consultation with RBI, the Union government decided to borrow ₹7.86 lakh crore through dated securities in the second half of FY 2026-27. The amount includes ₹15,000 crore of Sovereign Green Bonds and is scheduled through 23 weekly auctions.$$,
  $$This is public-finance and debt-management material. It distinguishes dated securities and Treasury Bills, and shows how government borrowing is planned across maturities rather than being one single loan.$$,
  $$The official plan spreads H2 dated-security borrowing over 3-, 5-, 7-, 10-, 15-, 30-, 40- and 50-year tenors. It also sets the H2 Ways and Means Advances limit at ₹50,000 crore; WMA is RBI’s temporary advance facility for mismatches in government accounts.$$,
  $$Government’s Borrowing Plan for the second half of FY 2026-27$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2315024&lang=1&reg=3$$,
  $$Ministry of Finance / Press Information Bureau$$, $$2026-09-25$$,
  $$["H2 FY 2026-27 dated-security borrowing is set at ₹7.86 lakh crore.","The plan includes ₹15,000 crore of Sovereign Green Bonds.","The borrowing is scheduled through 23 weekly auctions across eight maturity buckets.","The H2 Ways and Means Advances limit is ₹50,000 crore."]$$::jsonb,
  $$[{"question":"Which institution does the government consult for its borrowing programme?","answer":"The Reserve Bank of India."},{"question":"What are Ways and Means Advances used for?","answer":"Temporary mismatches in government accounts."}]$$::jsonb,
  $${"title":"Government debt-management sequence","steps":["The government estimates funding needs and consults RBI.","It announces securities, maturities and an auction schedule.","Investors bid in auctions and the government raises funds.","WMA can bridge temporary cash-flow mismatches separately."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-cpgrams-central-ministries-august-report$$, $$2026-09-27$$,
  $$CPGRAMS August report records 2.42 lakh grievance redressals by Central ministries$$,
  $$DARPG’s 52nd monthly CPGRAMS report says Central ministries and departments redressed 2,42,391 public grievances in August 2026. It reports an average disposal time of 13 days for 2026 and names the Department of Posts, Department of Telecommunications and DFS Insurance Division among the Group A GRAI performers.$$,
  $$This is a governance-data brief. It tests CPGRAMS as a grievance-redressal platform and GRAI as a performance assessment, not a welfare scheme or an appellate court.$$,
  $$CPGRAMS stands for Centralized Public Grievance Redress and Monitoring System. The report says it is available through over five lakh Common Service Centres and that the Review Meeting Module enables Secretary-level review; these are delivery and accountability mechanisms in administrative reform.$$,
  $$DARPG releases the 52nd Monthly Report on CPGRAMS for Central Ministries/Departments, August 2026$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314963&lang=1&reg=3$$,
  $$Department of Administrative Reforms and Public Grievances / Press Information Bureau$$, $$2026-09-25$$,
  $$["CPGRAMS stands for Centralized Public Grievance Redress and Monitoring System.","Central ministries and departments redressed 2,42,391 grievances in August 2026.","The release gives an average 2026 disposal time of 13 days for Central ministries/departments.","GRAI refers to the Grievance Redressal Assessment and Index."]$$::jsonb,
  $$[{"question":"Which department publishes the cited CPGRAMS monthly report?","answer":"The Department of Administrative Reforms and Public Grievances (DARPG)."},{"question":"What is GRAI used for?","answer":"It assesses grievance-redressal performance."}]$$::jsonb,
  $${"title":"Turning a grievance into governance feedback","steps":["A citizen files a grievance through CPGRAMS or an access channel.","The relevant department receives and processes the case.","Disposal data are reviewed through administrative dashboards and meetings.","Monthly reports and GRAI make performance comparable."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-minority-affairs-institutional-partnerships$$, $$2026-09-27$$,
  $$Minority Affairs Ministry signs institutional partnerships for monitoring, infrastructure and enterprise support$$,
  $$The Ministry of Minority Affairs entered partnerships with IIT Madras’ CUBE, IIM Bangalore, IISc-linked FSID and IIMB Innovations/NSRCEL. The agreements cover independent assessment of PMJVK infrastructure, third-party monitoring of PM VIKAS training, and entrepreneurship and innovation support through NMDFC.$$,
  $$This is a social-justice and programme-delivery item. The exam angle is the different institutional roles: PMJVK is an area-development programme, PM VIKAS provides development support including skilling, and NMDFC is a development-finance corporation.$$,
  $$Third-party assessment means an institution outside the implementing department evaluates quality, functioning and outcomes. The release says IIMB will monitor PM VIKAS training in the South zone, while IIT Madras’ CUBE will assess selected PMJVK infrastructure projects.$$,
  $$Minority Affairs Ministry partnerships with strategic institutions at IISc Bengaluru$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2315015&lang=1&reg=3$$,
  $$Ministry of Minority Affairs / Press Information Bureau$$, $$2026-09-25$$,
  $$["The partnerships involve CUBE IIT Madras, IIM Bangalore, FSID IISc and IIMB Innovations/NSRCEL.","IIM Bangalore will conduct third-party monitoring of PM VIKAS training in the South zone.","CUBE IIT Madras will assess selected PMJVK infrastructure projects.","NMDFC partnerships focus on entrepreneurship, innovation and enterprise development."]$$::jsonb,
  $$[{"question":"Which programme’s training is to receive third-party monitoring in the South zone?","answer":"PM VIKAS training."},{"question":"What is the value of third-party assessment?","answer":"It provides independent evidence on quality, functioning and outcomes."}]$$::jsonb,
  $${"title":"Evidence-led programme delivery","steps":["A ministry implements social-development programmes.","Academic and innovation institutions contribute specialised expertise.","Independent monitoring identifies quality and delivery gaps.","Evidence can improve future planning, assets and beneficiary outcomes."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-ifsca-differential-distribution-framework$$, $$2026-09-27$$,
  $$IFSCA issues a differential-distribution framework for select IFSC fund schemes$$,
  $$IFSCA issued a regulatory framework allowing differential distribution in Venture Capital Schemes and Restricted Schemes to facilitate blended-finance and other fund structures in the International Financial Services Centre.$$,
  $$This is a financial-regulation update. It is relevant for understanding why IFSC has a separate unified regulator and how fund structures can use different economic distributions without confusing them with retail mutual-fund products.$$,
  $$IFSCA is the unified authority established under the IFSCA Act, 2019 to regulate and develop financial products, services and institutions in India’s IFSCs. The framework applies to specified schemes under the IFSCA fund-management regime, rather than to every domestic investment product.$$,
  $$Framework for differential distribution in Venture Capital Schemes and Restricted Schemes to facilitate blended finance and other fund structures$$,
  $$https://ifsca.gov.in/PressRelease/Index?MId=gDbbVKz-6mo%3D$$,
  $$International Financial Services Centres Authority$$, $$2026-09-25$$,
  $$["IFSCA issued the framework on 25 September 2026.","It covers Venture Capital Schemes and Restricted Schemes in the IFSC context.","The stated purpose includes facilitating blended finance and other fund structures.","IFSCA is the unified regulator for financial services in India’s IFSCs."]$$::jsonb,
  $$[{"question":"Which authority regulates and develops financial services in India’s IFSCs?","answer":"The International Financial Services Centres Authority (IFSCA)."},{"question":"Does this framework automatically cover all domestic retail mutual funds?","answer":"No. The official item is framed for specified IFSC fund schemes."}]$$::jsonb,
  $${"title":"A specialised IFSC fund-regulation setting","steps":["A fund scheme is set up in an International Financial Services Centre.","The scheme follows the IFSCA fund-management regime.","A differential distribution structure can be designed within the permitted framework.","The structure can support blended-finance or specialised investment objectives."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-india-international-water-week-outcomes$$, $$2026-09-27$$,
  $$India International Water Week closes with climate-resilient water-management recommendations$$,
  $$The ninth India International Water Week concluded in New Delhi after discussions on climate-resilient water management. Its brief recommendations emphasised participatory water governance, safe reuse of treated wastewater, groundwater recharge, data-led planning, multi-hazard warning and river-basin approaches.$$,
  $$This is a water-governance update with direct links to SDG 6, Jal Jeevan Mission and local institutions. The value lies in the specific management concepts, not merely remembering that a conference was held.$$,
  $$The event released a Riverine Macroplastics Monitoring Protocol through the National Mission for Clean Ganga, capacity-building modules under Jal Jeevan Mission and reports on irrigation projects, minor irrigation, water bodies and springs. The release also highlighted Gram Panchayats and Pani Samitis in operations and maintenance.$$,
  $$9th India International Water Week 2026 concludes with focus on climate-resilient water management and sustainable water services$$,
  $$https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2315096&lang=2&reg=48$$,
  $$Ministry of Jal Shakti / Press Information Bureau$$, $$2026-09-25$$,
  $$["The 9th India International Water Week focused on climate-resilient water management.","Recommendations included treated-wastewater reuse, groundwater recharge and data-driven governance.","The National Mission for Clean Ganga released a Riverine Macroplastics Monitoring Protocol.","Gram Panchayats and Pani Samitis were highlighted for local operations and maintenance."]$$::jsonb,
  $$[{"question":"Which Sustainable Development Goal concerns clean water and sanitation?","answer":"SDG 6."},{"question":"Which mission released the Riverine Macroplastics Monitoring Protocol?","answer":"The National Mission for Clean Ganga."}]$$::jsonb,
  $${"title":"Climate-resilient water governance","steps":["Data and local knowledge identify water risks and service gaps.","Institutions plan source protection, reuse, recharge and reliable service.","Technology and early warning support monitoring and response.","Communities and local bodies sustain operations and accountability."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-27-csir-five-indian-language-science-magazines$$, $$2026-09-27$$,
  $$CSIR-NIScPR launches popular-science magazines in five Indian languages$$,
  $$CSIR-NIScPR launched new popular-science magazines in Assamese, Bengali, Marathi, Tamil and Telugu at CSIR’s 85th Foundation Day. The initiative combines selected AI-assisted translations with human review and original articles in the relevant language.$$,
  $$This is a science-communication and language-access item. It is useful for questions on CSIR’s role and for avoiding a common error: translation assistance does not replace editorial fact-checking in the stated model.$$,
  $$The five titles are Bigyan Lahar (Assamese), Bigyan Brittanto (Bengali), Vidnyan Kshitij (Marathi), Ariviyal Arikkaiyalar (Tamil) and Vigyan Velugu (Telugu). They add to CSIR-NIScPR’s existing Science Reporter (English), Vigyan Pragati (Hindi) and Science ki Duniya (Urdu).$$,
  $$CSIR-NIScPR launches popular science magazines in five Indian languages$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2315227&lang=1&reg=3$$,
  $$CSIR-National Institute of Science Communication and Policy Research / Press Information Bureau$$, $$2026-09-26$$,
  $$["The new CSIR-NIScPR magazines are in Assamese, Bengali, Marathi, Tamil and Telugu.","Bigyan Lahar is Assamese and Vigyan Velugu is Telugu.","The initiative uses AI-assisted translations followed by human review, proofing and fact-checking.","Science Reporter, Vigyan Pragati and Science ki Duniya are the stated English, Hindi and Urdu flagship magazines."]$$::jsonb,
  $$[{"question":"Which CSIR institute published the new magazines?","answer":"CSIR-National Institute of Science Communication and Policy Research (CSIR-NIScPR)."},{"question":"What quality-control step follows the AI-assisted translations?","answer":"Human expert review, proofreading, fact-checking and editorial refinement."}]$$::jsonb,
  $${"title":"Making science communication more accessible","steps":["Scientific material is selected for public communication.","Content is translated and adapted for a regional language.","Human experts check accuracy, language and readability.","Readers access science content alongside locally written articles."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
  $$2026-09-27-cgtmse-guarantee-cover-treds$$,
  $$2026-09-27-quad-at-sea-ship-observer-mission$$,
  $$2026-09-27-trai-digital-connectivity-rating-platform$$,
  $$2026-09-27-fcv-tobacco-growers-interest-free-loan$$,
  $$2026-09-27-india-h2-market-borrowing-plan$$,
  $$2026-09-27-cpgrams-central-ministries-august-report$$,
  $$2026-09-27-minority-affairs-institutional-partnerships$$,
  $$2026-09-27-ifsca-differential-distribution-framework$$,
  $$2026-09-27-india-international-water-week-outcomes$$,
  $$2026-09-27-csir-five-indian-language-science-magazines$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
